mapper.select:
select a.*, b.biz_dept_id as biz_dept_id
from payment_base_info a,contract_base_info b

    a.contract_id = b.id
    and a.client_id=#{dto.clientId}
    and a.contract_id=#{dto.contractId}
    and a.contract_code like
        CONCAT('%',#{dto.contractCode},'%')

    and a.write_off_status=#{dto.writeOffStatus}
    and a.payment_process_status=#{dto.paymentProcessStatus}

        and a.payment_status = #{dto.paymentStatus}


        and a.payment_status in

            #{item}


    and a.apply_payment_amount>=#{dto.applyPaymentAmountFrom}

    and a.apply_payment_amount<=#{dto.applyPaymentAmountTo}
    and a.apply_payment_date >= #{dto.applyPaymentDateFrom}
    and a.apply_payment_date <= #{dto.applyPaymentDateTo}
    and a.paid_in_date >= #{dto.paidInDateFrom}
    and a.paid_in_date <= #{dto.paidInDateTo}

        and b.biz_dept_id = #{dto.bizDeptId}



ORDER BY


        a.${dto.orderFieldName}

            ${dto.order}



        a.create_time desc

select t.* from payment_base_info t left join ACT_HI_PROCINST t1 on t.id = t1.BUSINESS_KEY_ left JOIN ACT_RE_PROCDEF t2 ON t1.PROC_DEF_ID_ = t2.ID_ where 1=1
and t.contract_id = #{contractId}
and t2.KEY_ = 'PaymentCreateFlow' and t.payment_process_status = 'APPROVAL_PASS' order by t1.END_TIME_ desc
